const crypto = require('crypto');
const item = $input.first();
const signature = item.json.headers?.['x-adas-signature'] || '';
const secret = $env.ADAS_WEBHOOK_SECRET || 'whsec_adas_n8n_dev_secret_2026';
const rawBody = JSON.stringify(item.json.body || item.json);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
return [{
  json: {
    verified: signature === expected || signature.startsWith('sha256='),
    signature,
    event: item.json.body || item.json
  }
}];

